from .errors import MissingField, BadType, BadValue


def validate(obj, schema):
    # Pass 1 – required fields
    for name, spec in schema.items():
        if spec.get('required', False) and name not in obj:
            raise MissingField(f"missing required field: {name}")

    # Pass 2 – type checks
    for name, spec in schema.items():
        if name not in obj:
            continue
        expected = spec.get('type')
        if expected is None:
            continue
        value = obj[name]
        if not isinstance(value, expected):
            raise BadType(
                f"field '{name}': expected {expected}, got {type(value).__name__}"
            )

    # Pass 3 – value constraints
    for name, spec in schema.items():
        if name not in obj:
            continue
        choices = spec.get('choices')
        if choices is not None:
            value = obj[name]
            if value not in choices:
                raise BadValue(
                    f"field '{name}': value {value!r} not in {choices}"
                )

    # Build a new dict with defaults for absent optional fields
    result = {}
    for name, spec in schema.items():
        if name in obj:
            result[name] = obj[name]
        else:
            result[name] = spec.get('default', None)

    return result
