import csv as _csv
import io
import os


DIALECTS = {'excel': ',', 'excel-tab': '\t', 'pipe': '|'}


class Reader:
    def __init__(self, source, dialect='excel', delimiter=None):
        if hasattr(source, 'read'):
            self._text = source.read()
        else:
            self._text = source
        self.delimiter = delimiter or DIALECTS.get(dialect, ',')

    def _make_reader(self):
        return _csv.reader(io.StringIO(self._text), delimiter=self.delimiter)

    @property
    def fieldnames(self):
        reader = self._make_reader()
        first_row = next(reader, [])
        return [name.strip() for name in first_row]

    def rows(self):
        reader = self._make_reader()
        header = next(reader, [])
        header = [name.strip() for name in header]
        for row in reader:
            if all(not cell.strip() for cell in row):
                continue
            d = {}
            for i, key in enumerate(header):
                if i < len(row):
                    d[key] = row[i].strip()
                else:
                    d[key] = None
            yield d

    @classmethod
    def read(cls, path_or_text, dialect='excel', delimiter=None):
        if os.path.exists(path_or_text):
            with open(path_or_text, 'r', newline='') as f:
                text = f.read()
            return cls(text, dialect=dialect, delimiter=delimiter)
        return cls(path_or_text, dialect=dialect, delimiter=delimiter)

    @classmethod
    def write(cls, path, fieldnames, rows, dialect='excel'):
        delimiter = DIALECTS.get(dialect, ',')
        with open(path, 'w', newline='') as f:
            writer = _csv.writer(f, delimiter=delimiter, quoting=_csv.QUOTE_MINIMAL)
            writer.writerow(fieldnames)
            for row in rows:
                writer.writerow([
                    '' if (v := row.get(k)) is None else v
                    for k in fieldnames
                ])
