"""Migration runner with dependency graph, rollback, and recording."""

import heapq

from .errors import MigrationError


def plan(migrations):
    """Return migration names in dependency order (alphabetical tie-break).

    Raises MigrationError on duplicate names, missing deps, or cycles.
    """
    names = [m['name'] for m in migrations]

    if len(names) != len(set(names)):
        raise MigrationError("duplicate migration names")

    name_set = set(names)
    in_degree = {name: 0 for name in names}
    dependents = {name: [] for name in names}

    for m in migrations:
        for dep in m.get('deps', []):
            if dep not in name_set:
                raise MigrationError(f"missing dependency: {dep}")
            in_degree[m['name']] += 1
            dependents[dep].append(m['name'])

    queue = sorted(name for name in names if in_degree[name] == 0)
    result = []

    while queue:
        current = heapq.heappop(queue)
        result.append(current)
        for dep in dependents[current]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(queue, dep)

    if len(result) != len(names):
        raise MigrationError("dependency cycle detected")

    return result


def applied(db):
    """Return the set of migration names already recorded in db."""
    return set(db.applied_migrations)


def migrate(conn, migrations, db, dry_run=False):
    """Apply planned migrations not yet recorded.

    Returns the list of names applied (in order).  On failure, rolls back
    everything applied during *this* call and re-raises the original exception.
    """
    planned = plan(migrations)
    already = applied(db)
    to_apply = [name for name in planned if name not in already]

    if dry_run:
        return to_apply

    migration_map = {m['name']: m for m in migrations}
    applied_this_call = []

    try:
        for name in to_apply:
            migration_map[name]['up'](conn)
            db.record(name)
            applied_this_call.append(name)
    except Exception:
        for name in reversed(applied_this_call):
            migration_map[name]['down'](conn)
            db.applied_migrations.remove(name)
        raise

    return applied_this_call


def rollback_last(conn, migrations, db):
    """Undo the most recently recorded migration.

    Returns the undone migration name, or None if nothing is recorded.
    """
    if not db.applied_migrations:
        return None

    name = db.applied_migrations[-1]
    migration_map = {m['name']: m for m in migrations}
    migration_map[name]['down'](conn)
    db.applied_migrations.remove(name)
    return name
