"""Expression parser."""

import re


class ExprError(Exception):
    pass


_NUM_RE = re.compile(r'\d+\.?\d*|\.\d+')
_OP_RE = re.compile(r'\*\*|//|[+\-*/%()]')


def tokenize(text):
    if not text or not text.strip():
        raise ExprError("empty expression")

    tokens = []
    i = 0
    while i < len(text):
        if text[i].isspace():
            i += 1
            continue

        m = _NUM_RE.match(text, i)
        if m:
            s = m.group()
            if '.' in s:
                tokens.append(float(s))
            else:
                tokens.append(int(s))
            i = m.end()
            continue

        m = _OP_RE.match(text, i)
        if m:
            tokens.append(m.group())
            i = m.end()
            continue

        raise ExprError(f"unexpected character: {text[i]!r}")

    if not tokens:
        raise ExprError("empty expression")

    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        result = self.expr()
        if self.pos != len(self.tokens):
            raise ExprError("trailing tokens")
        return result

    def expr(self):
        left = self.term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def term(self):
        left = self.unary()
        while self.peek() in ('*', '/', '//', '%'):
            op = self.consume()
            right = self.unary()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ExprError("division by zero")
                left = left / right
            elif op == '//':
                if right == 0:
                    raise ExprError("division by zero")
                left = left // right
            else:
                if right == 0:
                    raise ExprError("division by zero")
                left = left % right
        return left

    def unary(self):
        if self.peek() in ('+', '-'):
            op = self.consume()
            operand = self.unary()
            if op == '-':
                return -operand
            return operand
        return self.power()

    def power(self):
        base = self.atom()
        if self.peek() == '**':
            self.consume()
            exp = self.unary()
            return base ** exp
        return base

    def atom(self):
        tok = self.peek()
        if tok is None:
            raise ExprError("unexpected end of expression")
        if isinstance(tok, (int, float)):
            self.consume()
            return tok
        if tok == '(':
            self.consume()
            result = self.expr()
            if self.peek() != ')':
                raise ExprError("unbalanced parentheses")
            self.consume()
            return result
        raise ExprError(f"unexpected token: {tok!r}")


