"""Draining pipeline."""


class DrainError(Exception):
    def __init__(self, message, items=None, cause=None):
        super().__init__(message)
        self.items = list(items or [])
        self.cause = cause


def collect(source, batch_size=100):
    out = []
    try:
        if hasattr(source, 'read_batch'):
            while True:
                b = source.read_batch(batch_size)
                if not b:
                    break
                out.extend(b)
        else:
            for item in source:
                out.append(item)
    except Exception as exc:
        raise DrainError(str(exc), items=out, cause=exc) from exc
    finally:
        source.close()
    return out


def drain(source):
    try:
        for item in source:
            yield item
    except GeneratorExit:
        source.close()
        raise
    else:
        source.close()


def close_all(sources):
    errors = []
    for source in sources:
        try:
            source.close()
        except Exception as exc:
            errors.append(exc)
    if errors:
        messages = "; ".join(str(e) for e in errors)
        raise DrainError(messages, items=[], cause=errors[0])
