```file depgraph/graph.py
"""Dependency graph."""


class Graph:
    def __init__(self):
        self._mods = {}

    def add_module(self, name, provides=(), requires=()):
        self._mods[name] = (set(provides), set(requires))

    def dependents(self, name):
        return sorted(m for m, (_, req) in self._mods.items() if name in req)

    def _module_deps(self, name):
        """Modules that directly depend on module *name* (module-to-module edge)."""
        if name not in self._mods:
            return set()
        provides_of_name = self._mods[name][0]
        result = set()
        for m, (_, req) in self._mods.items():
            if m == name:
                continue
            if name in req:
                result.add(m)
            elif req & provides_of_name:
                result.add(m)
        return result

    def _adjacency(self):
        """Full module-to-module adjacency including self-loops."""
        adj = {m: set() for m in self._mods}
        for m, (_, req) in self._mods.items():
            for r in req:
                if r in self._mods:
                    adj[m].add(r)
                for p, (prov, _) in self._mods.items():
                    if r in prov:
                        adj[m].add(p)
        return adj

    def reverse_closure(self, name):
        if name in self._mods:
            start = {name}
        else:
            start = {m for m, (prov, _) in self._mods.items() if name in prov}
        result = set()
        queue = list(start)
        while queue:
            current = queue.pop()
            if current in result:
                continue
            result.add(current)
            for dep in self._module_deps(current):
                if dep not in result:
                    queue.append(dep)
        return result

    def invalidate(self, name):
        to_remove = self.reverse_closure(name)
        for m in to_remove:
            del self._mods[m]
        return to_remove

    def missing(self):
        all_provides = set()
        all_requires = set()
        for prov, req in self._mods.values():
            all_provides |= prov
            all_requires |= req
        return sorted(all_requires - all_provides)

    def cycles(self):
        adj = self._adjacency()
        nodes = sorted(self._mods.keys())
        found = []
        for start in nodes:
            stack = [(start, [start], {start})]
            while stack:
                node, path, path_set = stack.pop()
                for neighbor in adj.get(node, set()):
                    if neighbor == start:
                        cycle = tuple(sorted(path))
                        if cycle not in found:
                            found.append(cycle)
                    elif neighbor > start and neighbor not in path_set:
                        stack.append((neighbor, path + [neighbor], path_set | {neighbor}))
        return sorted(found)

    def to_json(self):
        return {
            name: {
                'provides': sorted(prov),
                'requires': sorted(req),
            }
            for name, (prov, req) in self._mods.items()
        }
