    def __init__(self, initial, states, on_transition=None):
        self.initial = initial
        self.states = states
        self.state = initial
        self.history = [initial]
        self.on_transition = on_transition
        self._open_regions = {}
        self._current_region = None
        self._current_branch = None

    def _is_parallel(self, state_name):
        defn = self.states.get(state_name)
        return isinstance(defn, dict) and 'parallel' in defn

    def _get_transitions(self, state_name):
        defn = self.states.get(state_name)
        if defn is None:
            return None
        if isinstance(defn, dict) and 'parallel' in defn:
            return defn['parallel']
        return defn

    def _find_transition(self, src, target):
        transitions = self._get_transitions(src)
        if transitions is None:
            return None
        for t in transitions:
            if isinstance(t, dict):
                if t.get('to') == target:
                    return t
            elif t == target:
                return {'to': target}
        return None

    def go(self, target, **ctx):
        src = self.state

        if target not in self.states:
            raise UnknownState(target)

        transition = self._find_transition(src, target)

        # Entering a branch of an open parallel region from any state inside it
        if transition is None and self._current_region is not None:
            region_info = self._open_regions.get(self._current_region)
            if region_info and target in region_info['branches']:
                transition = {'to': target}

        if transition is None:
            raise UnknownState(target)

        # Guard check – nothing changes on failure
        guard = transition.get('guard')
        if guard is not None:
            if not guard(**ctx):
                raise GuardFailed(f"Guard failed for transition {src} -> {target}")

        # Snapshot for rollback
        saved_state = src
        saved_history_len = len(self.history)
        saved_region = self._current_region
        saved_branch = self._current_branch
        saved_open_regions = {
            k: {'branches': list(v['branches']), 'entered': set(v['entered']), 'completed': set(v['completed'])}
            for k, v in self._open_regions.items()
        }

        # Apply transition
        self.state = target
        self.history.append(target)

        # Parallel-region bookkeeping
        if self._is_parallel(target):
            self._open_regions[target] = {
                'branches': list(self.states[target]['parallel']),
                'entered': set(),
                'completed': set(),
            }
            self._current_region = target
            self._current_branch = None
        elif (self._current_region is not None
              and target in self._open_regions.get(self._current_region, {}).get('branches', [])):
            self._open_regions[self._current_region]['entered'].add(target)
            self._current_branch = target

        # Terminal state marks branch completion
        if self._current_branch is not None and self._current_region is not None:
            transitions = self._get_transitions(target)
            if transitions is not None and len(transitions) == 0:
                self._open_regions[self._current_region]['completed'].add(self._current_branch)
                region_info = self._open_regions[self._current_region]
                if region_info['completed'] == set(region_info['branches']):
                    self._current_region = None
                    self._current_branch = None

        # Action runs after state is updated
        action = transition.get('action')
        if action is not None:
            try:
                result = action(target)
            except Exception:
                self.state = saved_state
                self.history = self.history[:saved_history_len]
                self._current_region = saved_region
                self._current_branch = saved_branch
                self._open_regions = saved_open_regions
                raise
            if result is not None:
                if self.on_transition:
                    self.on_transition(src, target)
                return result

        if self.on_transition:
            self.on_transition(src, target)

        return target

    def join(self, name):
        if name not in self.states:
            raise NotParallel(name)
        if not self._is_parallel(name):
            raise NotParallel(name)
        region_info = self._open_regions.get(name)
        if region_info is None:
            return False
        return region_info['completed'] == set(region_info['branches'])
